// Notes are private to their creator.

export async function updateNote(db, member, id, text) {
  const result = await db.prepare(
    "UPDATE notes SET text = ? WHERE id = ? AND owner_id = ?"
  ).bind(text, id, member.id).run();
  return result.meta.changes;
}

