// Called by guarded platform dispatch for GET and POST.
export async function handler({ context, method, input }, archiveAll) {
  if (method !== "POST") return new Response(null, { status: 405 });
  context.requirePermission("notes.archive");
  await archiveAll(context.member.id);
  return new Response(null, { status: 204 });
}

